select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Liner (research agents)' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Assistant de recherche IA qui cite ses sources, avec des agents pour les revues de littérature, la formulation d''hypothèses, les recommandations de citations, les enquêtes et la relecture.',
  'AI research assistant with cited answers and research agents for literature reviews, hypothesis generation, citation recommendations, surveys and peer review.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Fellou' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Navigateur IA agentique qui réalise des tâches sur les sites à votre place : recherche approfondie sur de nombreux sites, remplissage de formulaires et processus en plusieurs étapes, puis compte rendu.',
  'Agentic AI browser that carries out tasks on websites for you: deep research across many sites, form filling and multi-step workflows, then reports back.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Dia' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Navigateur IA dont l''assistant travaille avec vos onglets ouverts et vos outils connectés pour trouver, résumer, rédiger et construire ce dont vous avez besoin.',
  'AI browser whose assistant works with your open tabs and connected tools to find, summarize, draft and build what you need.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Rows AI Analyst' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Tableur avec un analyste IA qui extrait les données des PDF et des images, nettoie les tableaux et répond aux questions d''analyse en langage courant.',
  'Spreadsheet with an AI analyst that extracts data from PDFs and images, cleans tables and answers analysis questions in plain language.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Gemini Enterprise' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'La plateforme d''agents de Google pour les entreprises : agents prêts à l''emploi comme Deep Research, création sans code de processus en plusieurs étapes entre les applications, et recherche dans les données de l''entreprise.',
  'Google''s enterprise agent platform: prebuilt agents such as Deep Research, a no-code builder for multi-step workflows across company apps, and search over company data.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Airtable Omni' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'L''IA d''Airtable qui crée et met à jour des bases et des applications à partir d''une demande, remplit et analyse les fiches avec des champs IA, et exécute des processus d''agents sur vos données.',
  'Airtable''s AI that builds and updates bases and apps from a request, fills and analyzes records with AI fields, and runs agent workflows on your data.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'monday.com AI agents' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Créateur d''agents sans code dans monday.com : les équipes créent, lancent et gèrent des agents IA qui mettent à jour les tableaux, trient les demandes et exécutent les processus des services.',
  'No-code agent builder inside monday.com: teams create, launch and manage AI agents that update boards, triage requests and run department workflows.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'hireEZ (EZ Agent)' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Plateforme de recrutement par agents IA qui trouve les candidats, les présélectionne et les contacte, et tient l''ATS à jour pour les équipes de recrutement et de staffing.',
  'Agentic AI recruiting platform that sources candidates, screens and engages them, and keeps the ATS up to date for recruiting and staffing teams.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Akkio' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Plateforme d''analyse IA pour les agences média, avec des agents spécialisés qui analysent les données de campagne, prévoient les résultats et produisent les rapports clients.',
  'AI analytics platform for media agencies, with domain-specific agents that analyze campaign data, forecast results and build reports for clients.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Flowith (Agent Neo)' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Espace de travail IA avec Agent Neo, un agent qui mène de longues tâches en plusieurs étapes comme la recherche approfondie, les présentations et les sites web sur une toile infinie.',
  'AI workspace with Agent Neo, an agent that runs long multi-step jobs such as deep research, slide decks and websites on an infinite canvas.');

select refresh_rankings();

select e.name, 'https://electraindex.com/agents/' || e.slug as page,
       (select count(*) from entities x where x.type = 'agent' and x.is_published) as agents_total
  from entities e where e.type = 'agent' and e.name in ('Liner (research agents)', 'Fellou', 'Dia', 'Rows AI Analyst', 'Gemini Enterprise', 'Airtable Omni', 'monday.com AI agents', 'hireEZ (EZ Agent)', 'Akkio', 'Flowith (Agent Neo)') order by e.name;
